22	var mockHRBase = 72
23	var mockHRDrift = 0
24	
25	function mockHeartRate() {
26	  mockHRDrift += (Math.random() - 0.5) * 0.4
27	  if (mockHRDrift > 6) { mockHRDrift = 6 }
28	  if (mockHRDrift < -6) { mockHRDrift = -6 }
29	  var hr = mockHRBase + mockHRDrift + 0.8 * Math.sin(Date.now() / 15000)
