216	// ─── 步数估算 ──────────────────────────────────────────
217	
218	var stepCount = 0
219	var lastStepTime = 0
220	var STEP_THRESHOLD = 1.25
221	var STEP_DEBOUNCE_MS = 280
222	
223	export function resetStepCount() {
224	  stepCount = 0
225	  lastStepTime = 0
226	}
227	
228	export function getStepCount() {
229	  return stepCount
230	}
231	
232	export function processStepDetection(sample) {
233	  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
234	  var now = Date.now()
235	  if (g > STEP_THRESHOLD && now - lastStepTime > STEP_DEBOUNCE_MS) {
236	    stepCount += 1
237	    lastStepTime = now
238	  }
239	  return stepCount
240	}
