251	export function getPressureTrend() {
252	  if (pressureHistory.length < 10) { return { delta: 0, trend: "stable" } }
253	  var recent = pressureHistory.slice(-30)
254	  var old = pressureHistory.slice(0, Math.min(30, pressureHistory.length))
255	  var recentAvg = 0
256	  var oldAvg = 0
257	  for (var i = 0; i < recent.length; i++) { recentAvg += recent[i].value }
258	  for (var j = 0; j < old.length; j++) { oldAvg += old[j].value }
259	  recentAvg /= recent.length
260	  oldAvg /= old.length
261	  var delta = recentAvg - oldAvg
262	  var trend = "stable"
263	  if (delta < -0.3) { trend = "falling" }
264	  else if (delta > 0.3) { trend = "rising" }
265	  return { delta: Math.round(delta * 100) / 100, trend: trend }
266	}
