281	export function getHRAverage(seconds) {
282	  if (!hrHistory.length) { return 0 }
283	  var cutoff = Date.now() - seconds * 1000
284	  var sum = 0
285	  var count = 0
286	  for (var i = hrHistory.length - 1; i >= 0; i--) {
287	    if (hrHistory[i].time < cutoff) { break }
288	    sum += hrHistory[i].value
289	    count += 1
290	  }
291	  return count > 0 ? Math.round(sum / count) : 0
292	}
