/**
 * anim-utils.js - 动画工具库
 *
 * 为圆形手表提供流畅的微动画：
 * - 弧线生长动画（Canvas 进度环）
 * - 数字滚动动画（心率、步数）
 * - 按钮按压缩放反馈
 * - 页面入场淡入效果
 */

// ─── 缓动函数 ──────────────────────────────────────────

export function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3)
}

export function easeOutQuart(t) {
  return 1 - Math.pow(1 - t, 4)
}

export function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

export function easeOutBack(t) {
  var c1 = 1.70158
  var c3 = c1 + 1
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2)
}

// ─── Canvas 弧线生长动画 ────────────────────────────────

/**
 * 绘制带动画的进度弧线
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} cx - 圆心 x
 * @param {number} cy - 圆心 y
 * @param {number} r - 半径
 * @param {number} lineWidth - 线宽
 * @param {number} fromAngle - 起始角度（弧度）
 * @param {number} toAngle - 目标角度（弧度）
 * @param {string} color - 颜色
 * @param {number} duration - 动画时长 ms
 * @param {function} onProgress - 进度回调 (0~1)
 * @param {function} onComplete - 完成回调
 */
export function animateArc(ctx, cx, cy, r, lineWidth, fromAngle, toAngle, color, duration, onProgress, onComplete) {
  var startTime = Date.now()
  var angleDelta = toAngle - fromAngle

  function frame() {
    var elapsed = Date.now() - startTime
    var t = Math.min(elapsed / duration, 1)
    var eased = easeOutCubic(t)
    var currentAngle = fromAngle + angleDelta * eased

    ctx.beginPath()
    ctx.lineWidth = lineWidth
    ctx.strokeStyle = color
    ctx.lineCap = "round"
    ctx.arc(cx, cy, r, fromAngle, currentAngle)
    ctx.stroke()

    if (onProgress) { onProgress(t) }

    if (t < 1) {
      setTimeout(frame, 16)
    } else {
      if (onComplete) { onComplete() }
    }
  }

  frame()
}

// ─── 数字滚动动画 ──────────────────────────────────────

/**
 * 数字从 fromVal 滚动到 toVal
 * @param {number} fromVal - 起始值
 * @param {number} toVal - 目标值
 * @param {number} duration - 动画时长 ms
 * @param {function} onUpdate - 每帧回调 (当前值)
 * @param {function} onComplete - 完成回调
 */
export function animateNumber(fromVal, toVal, duration, onUpdate, onComplete) {
  var startTime = Date.now()
  var delta = toVal - fromVal

  function frame() {
    var elapsed = Date.now() - startTime
    var t = Math.min(elapsed / duration, 1)
    var eased = easeOutCubic(t)
    var current = Math.round(fromVal + delta * eased)

    if (onUpdate) { onUpdate(current) }

    if (t < 1) {
      setTimeout(frame, 16)
    } else {
      if (onComplete) { onComplete() }
    }
  }

  frame()
}

// ─── 脉搏动画（心率区域）────────────────────────────────

/**
 * 创建脉搏动画控制器
 * @param {number} bpm - 心率值
 * @returns {object} { start, stop, getScale, getOpacity }
 */
export function createPulseAnimator(bpm) {
  var timer = null
  var phase = 0
  var interval = bpm > 0 ? Math.round(60000 / bpm) : 1000

  function start() {
    stop()
    interval = bpm > 0 ? Math.round(60000 / bpm) : 1000
    timer = setInterval(function() {
      phase = (phase + 1) % 4
    }, Math.round(interval / 4))
  }

  function stop() {
    if (timer) { clearInterval(timer); timer = null }
    phase = 0
  }

  function getScale() {
    // 脉搏效果：1.0 → 1.08 → 1.0 → 0.96 → 1.0
    var scales = [1.0, 1.08, 1.0, 0.96, 1.0]
    return scales[phase] || 1.0
  }

  function getOpacity() {
    var opacities = [1.0, 0.9, 1.0, 0.95, 1.0]
    return opacities[phase] || 1.0
  }

  function updateBpm(newBpm) {
    bpm = newBpm
    if (timer) { start() }
  }

  return { start: start, stop: stop, getScale: getScale, getOpacity: getOpacity, updateBpm: updateBpm }
}

// ─── 按钮按压动画类 ────────────────────────────────────

/**
 * 获取按钮按压样式
 * @param {boolean} pressed - 是否按下
 * @param {string} baseStyle - 基础样式
 * @returns {string} 带缩放的样式
 */
export function getButtonPressStyle(pressed, baseStyle) {
  if (pressed) {
    return (baseStyle || "") + " transform: scale(0.95); opacity: 0.85;"
  }
  return baseStyle || ""
}

// ─── 页面入场动画类 ────────────────────────────────────

/**
 * 创建页面入场动画状态
 * @returns {object} { getStyle, trigger }
 */
export function createPageEnterAnimation() {
  var opacity = 0
  var translateY = 20
  var done = false

  function trigger() {
    if (done) return
    var startTime = Date.now()
    var duration = 300

    function frame() {
      var elapsed = Date.now() - startTime
      var t = Math.min(elapsed / duration, 1)
      var eased = easeOutCubic(t)

      opacity = eased
      translateY = 20 * (1 - eased)

      if (t < 1) {
        setTimeout(frame, 16)
      } else {
        done = true
      }
    }

    frame()
  }

  function getStyle() {
    return "opacity: " + opacity.toFixed(2) + "; transform: translateY(" + translateY.toFixed(1) + "px);"
  }

  return { trigger: trigger, getStyle: getStyle }
}

// ─── 列表项交错入场 ────────────────────────────────────

/**
 * 创建列表交错动画
 * @param {number} count - 项目数
 * @param {number} staggerMs - 每项延迟
 * @returns {function} getItemStyle(index)
 */
export function createStaggerAnimation(count, staggerMs) {
  staggerMs = staggerMs || 50
  var startTime = Date.now()
  var itemDuration = 250

  return function getItemStyle(index) {
    var delay = index * staggerMs
    var elapsed = Date.now() - startTime - delay
    if (elapsed < 0) {
      return "opacity: 0; transform: translateY(12px);"
    }
    var t = Math.min(elapsed / itemDuration, 1)
    var eased = easeOutCubic(t)
    var opacity = eased
    var translateY = 12 * (1 - eased)
    return "opacity: " + opacity.toFixed(2) + "; transform: translateY(" + translateY.toFixed(1) + "px);"
  }
}

/**
 * touch-feedback.js - 触摸反馈工具
 *
 * 为手表应用提供统一的触摸反馈：
 * - 按钮按压缩放 + 颜色变化
 * - 列表项按压高亮
 * - 振动反馈（轻触/重触）
 */

import vibrator from "@system.vibrator"

// ─── 振动反馈 ──────────────────────────────────────────

export function vibrateLight() {
  try { vibrator.vibrate({ mode: "short" }) } catch (e) { /* skip */ }
}

export function vibrateMedium() {
  try { vibrator.vibrate({ mode: "long" }) } catch (e) { /* skip */ }
}

// ─── 按钮按压样式生成器 ──────────────────────────────────

/**
 * 生成按钮的按压态样式字符串
 * @param {string} normalBg - 正常背景色
 * @param {string} pressedBg - 按压背景色（可选，默认变暗15%）
 * @returns {object} { normalStyle, pressedStyle, onTouchStart, onTouchEnd }
 */
export function createButtonFeedback(normalBg, pressedBg) {
  var pressed = false

  function onTouchStart() {
    pressed = true
    vibrateLight()
  }

  function onTouchEnd() {
    pressed = false
  }

  function isPressed() {
    return pressed
  }

  return {
    onTouchStart: onTouchStart,
    onTouchEnd: onTouchEnd,
    isPressed: isPressed
  }
}

// ─── 列表项反馈样式 ────────────────────────────────────

/**
 * 生成列表项按压态
 * @param {string} normalBg - 正常背景色（如 #14201c）
 * @returns {string} 按压时的额外样式
 */
export function getListItemPressedStyle(normalBg) {
  return "background-color: " + (normalBg || "#1a2e28") + "; opacity: 0.8;"
}

// ─── 通用交互状态管理 ──────────────────────────────────

/**
 * 创建交互状态管理器
 * 用于管理按钮/卡片的按压状态和视觉反馈
 */
export function createInteractionState() {
  var state = {
    pressedId: null,
    pressedAt: 0
  }

  function press(id) {
    state.pressedId = id
    state.pressedAt = Date.now()
    vibrateLight()
  }

  function release() {
    state.pressedId = null
  }

  function isPressed(id) {
    return state.pressedId === id
  }

  function getPressedStyle(id, normalStyle) {
    if (state.pressedId === id) {
      return (normalStyle || "") + " opacity: 0.8; transform: scale(0.97);"
    }
    return normalStyle || ""
  }

  return {
    press: press,
    release: release,
    isPressed: isPressed,
    getPressedStyle: getPressedStyle
  }
}

