// ─── 模拟数据生成（真实化版本）────────────────────────────

var mockStartTime = Date.now()

// 随机游走状态
var walkState = {
  hr: 72, hrVelocity: 0,
  accelX: 0, accelY: 0, accelZ: 1,
  gyroX: 0, gyroY: 0, gyroZ: 0,
  pressure: 1013.25,
  stepPhase: 0, lastStepTime: 0
}

// 带随机游走的平滑更新
function randomWalk(current, velocity, target, damping, noise) {
  var force = (target - current) * 0.02
  velocity = velocity * damping + force + (Math.random() - 0.5) * noise
  return { value: current + velocity, velocity: velocity }
}

function mockAccel() {
  var now = Date.now()
  var elapsed = (now - mockStartTime) / 1000

  // 模拟真实步行/静止的加速度特征
  // 步行时有周期性的垂直分量波动（步态特征）
  var isWalking = walkState.hr > 80
  var stepFreq = isWalking ? 1.8 : 0  // 约 1.8Hz 步频
  var stepAmplitude = isWalking ? 0.35 : 0.02

  // 垂直分量：重力 + 步态周期 + 呼吸微动
  var gravity = 1.0
  var gait = stepAmplitude * Math.sin(elapsed * stepFreq * Math.PI * 2)
  var breath = 0.015 * Math.sin(elapsed * 0.3)
  var noise = (Math.random() - 0.5) * 0.02

  // 水平分量：轻微摆动 + 步态同步
  var swayX = 0.08 * Math.sin(elapsed * stepFreq * Math.PI * 2 + 0.5) + (Math.random() - 0.5) * 0.01
  var swayY = 0.06 * Math.cos(elapsed * stepFreq * Math.PI * 2 + 1.0) + (Math.random() - 0.5) * 0.01

  // 随机游走平滑
  walkState.accelX = walkState.accelX * 0.7 + (swayX) * 0.3
  walkState.accelY = walkState.accelY * 0.7 + (swayY) * 0.3
  walkState.accelZ = walkState.accelZ * 0.85 + (gravity + gait + breath + noise) * 0.15

  return {
    x: walkState.accelX,
    y: walkState.accelY,
    z: walkState.accelZ
  }
}

function mockGyro() {
  var now = Date.now()
  var elapsed = (now - mockStartTime) / 1000

  // 陀螺仪：静止时接近 0，步行时有小幅摆动
  var isWalking = walkState.hr > 80
  var base = isWalking ? 0.15 : 0.01
  var freq = isWalking ? 1.8 : 0.3

  var rx = base * Math.sin(elapsed * freq * 2.1) + (Math.random() - 0.5) * 0.008
  var ry = base * 0.7 * Math.cos(elapsed * freq * 1.7) + (Math.random() - 0.5) * 0.006
  var rz = base * 0.4 * Math.sin(elapsed * freq * 1.3 + 0.8) + (Math.random() - 0.5) * 0.004

  walkState.gyroX = walkState.gyroX * 0.8 + rx * 0.2
  walkState.gyroY = walkState.gyroY * 0.8 + ry * 0.2
  walkState.gyroZ = walkState.gyroZ * 0.8 + rz * 0.2

  return { x: walkState.gyroX, y: walkState.gyroY, z: walkState.gyroZ }
}

var mockHRBase = 72
var mockHRDrift = 0
var mockHRPhase = 0

function mockHeartRate() {
  // 心率随机游走：模拟真实的心率变异性（HRV）
  var result = randomWalk(walkState.hr, walkState.hrVelocity, mockHRBase, 0.92, 0.3)
  walkState.hr = Math.max(55, Math.min(120, result.value))
  walkState.hrVelocity = result.velocity

  // 添加呼吸性窦性心律不齐（约 0.25Hz）
  mockHRPhase += 0.025
  var hrv = 2.5 * Math.sin(mockHRPhase)

  var hr = Math.round(walkState.hr + hrv)
  return { heartRate: Math.max(50, Math.min(130, hr)) }
}

