  var drift = 0.001 * Math.sin(Date.now() / 60000)
  var noise = (Math.random() - 0.5) * 0.05
  walkState.pressure = walkState.pressure * 0.999 + (1013.25 + drift + noise) * 0.001
  return { pressure: walkState.pressure }
}

function mockCompass() {
  return { direction: 180 + 3 * Math.sin(Date.now() / 25000) + (Math.random() - 0.5), accuracy: 2 }
}

