var stepCount = 0
var lastStepTime = 0
var STEP_THRESHOLD = 1.25
var STEP_DEBOUNCE_MS = 280

export function resetStepCount() {
  stepCount = 0
  lastStepTime = 0
}

export function getStepCount() {
  return stepCount
}

export function processStepDetection(sample) {
  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
  var now = Date.now()
  if (g > STEP_THRESHOLD && now - lastStepTime > STEP_DEBOUNCE_MS) {
