  }
  return stepCount
}

input.new_string:
// ─── 步数估算（峰值检测 + 去抖）──────────────────────────

var stepCount = 0
var lastStepTime = 0
var STEP_DEBOUNCE_MS = 250
var stepHistory = []
var STEP_WINDOW = 6  // 检测窗口大小
var lastPeakValue = 0
var isRising = false

export function resetStepCount() {
  stepCount = 0
  lastStepTime = 0
  stepHistory = []
  lastPeakValue = 0
  isRising = false
}

export function getStepCount() {
  return stepCount
}

export function processStepDetection(sample) {
  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
  var now = Date.now()

  stepHistory.push(g)
  if (stepHistory.length > STEP_WINDOW * 2) {
    stepHistory.shift()
  }

  // 峰值检测算法：
  // 1. 追踪信号上升/下降状态
  // 2. 当从上升转为下降时，检测到峰值
  // 3. 峰值需超过动态阈值（基于近期均值）
  if (stepHistory.length >= 3) {
    var len = stepHistory.length
    var prev2 = stepHistory[len - 3]
    var prev1 = stepHistory[len - 2]
    var curr = stepHistory[len - 1]

    // 计算近期均值作为基准
    var sum = 0
    var count = Math.min(len, STEP_WINDOW)
    for (var i = len - count; i < len; i++) {
      sum += stepHistory[i]
    }
    var avg = sum / count
    var dynamicThreshold = avg + 0.12  // 动态阈值：均值 + 偏移量

    // 检测上升转下降（峰值）
    if (prev2 < prev1 && prev1 > curr && prev1 > dynamicThreshold) {
      if (now - lastStepTime > STEP_DEBOUNCE_MS) {
        stepCount += 1
        lastStepTime = now
        lastPeakValue = prev1
      }
    }
  }

  return stepCount
}

